using System;using System.IO;using System.Linq;using System.Text.RegularExpressions;using System.Collections.Generic;using System.Xml.Linq;using V15Voice;
public static class StableRepairTests {
 static int n;static string root;
 static void Check(bool v,string name){if(!v)throw new Exception(name);n++;Console.WriteLine("PASS "+name);}
 public sealed class E:KokoroEngine {public static List<string> Calls=new List<string>();public Func<string,double> Duration;public bool Fail;public override void CheckFiles(){if(Fail)throw new Exception("CUDA fixture failure");}public override Wave Generate(string text,double speed,string output){Calls.Add(text);double d=Duration==null?new Cue{Text=text}.Words*.30:Duration(text);return Tone(d/speed);}}
 static Wave Tone(double d){return new Wave{Rate=24000,Samples=Enumerable.Range(0,(int)Math.Round(d*24000)).Select(i=>(short)(4500*Math.Cos(i*.061))).ToArray()};}
 sealed class SlowEngine:KokoroEngine {public override void CheckFiles(){}public override Wave Generate(string text,double speed,string output){while(!Cancelled)System.Threading.Thread.Sleep(10);throw new OperationCanceledException();}}
 sealed class W:ITextRewriter {public int Calls;public Func<int,string> Reply;public string LastPrompt;public string Rewrite(string prompt,Func<bool> cancel,Action<string> activity){LastPrompt=prompt;Calls++;if(cancel())throw new OperationCanceledException();return Reply(Calls);}}
 static string Json(int id,string text){return LocalAi.Json(new AiRewriteText{cues=new List<AiCueText>{new AiCueText{id=id,text=text}}});}
 static VoiceSettings Settings(bool anchored=false){return new VoiceSettings{Mode=anchored?2:0,AiMode=2,Key="K:3",Slow=false,Breathing=2,Normalize=false,MaxSpeed=1.25,GentleFit=true};}
 static List<Cue> One(string text,double end=2.65){return new List<Cue>{new Cue{Id=1,Start=0,End=end,Text=text}};}
 static AiRepairSession Open(string name,List<Cue> cues,VoiceSettings settings=null){string path=Path.Combine(root,name+".srt");File.WriteAllText(path,Scripts.ToSrt(cues));return AiRepairSession.Open(path,cues,root,settings??Settings(),false,"fixture-profile");}
 static KokoroEngine New(string role){return new E{Root=root,VoiceName="Fixture "+role,DeviceMode="cpu",Archive=new SpeechArchive(Path.Combine(root,"tts-cache"))};}
 static void Run(AiRepairSession p,W w,bool accept=true,int id=0){AiTimeline.Run(p,w,New,()=>false,(i,m)=>{},accept,true,id);}
 static string Stem(string wav){return Path.Combine(Path.GetDirectoryName(wav),Path.GetFileNameWithoutExtension(wav));}
 public static int Main(){try{root=Path.Combine(Path.GetTempPath(),"V15 stable215 "+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);
  var original=One("John did not expect the door to open that day.");var p=Open("safe",original);string hash=StateFiles.Hash(p.Source);var w=new W{Reply=i=>Json(1,"John didn't expect the door to open that day.")};Run(p,w);
  Check(p.Rows[0].Chosen!=null&&p.Rows[0].Chosen.SemanticSafe,"Unambiguous contraction is measured with the same voice before automatic acceptance");
  Check(w.Calls==1&&p.Rows[0].AutoAttempts==1,"Stop after an acceptable natural-speed candidate, without unnecessary elaboration");
  Check(w.LastPrompt.Contains("signed after-fit delta=")&&w.LastPrompt.Contains("actual after-fit="),"Prompt receives actual signed seconds and measured target, not a fixed word budget");
  var used=p.Effective();var o=AudioRepair.Options(p.Settings);o.AiRepair=p;o.ReportContext=new VoiceReportContext{SourcePath=p.Source,SourceCues=used};string output;using(var e=New("A"))output=Renderer.Render(used,e,o,Path.Combine(root,"safe.wav"),(i,m)=>{});
  string stem=Stem(output);Check(new[]{".wav",".final.srt",".final.vi.txt",".ai-repair-report.txt",".voice-report.txt"}.All(x=>File.Exists(stem+x)),"Successful render publishes all five matching outputs");
  var final=Scripts.ParseSrt(File.ReadAllText(stem+".final.srt"));Check(final[0].Text==used[0].Text&&final[0].Start==0&&final[0].End==2.65,"Final SRT uses the actual accepted narration and keeps source timecode");
  Check(File.ReadAllText(stem+".final.vi.txt").Contains("EN: "+used[0].Text)&&File.ReadAllText(stem+".final.vi.txt").Contains("VI: [CHƯA DỊCH]"),"Vietnamese comparison file matches final English and explicitly marks untranslated text");
  Check(File.ReadAllText(stem+".ai-repair-report.txt").Contains("FINAL VERIFIED · AI FIXED")&&File.ReadAllText(stem+".voice-report.txt").Contains("FINAL VERIFIED · AI FIXED"),"AI and Voice reports agree on measured repair and final verification");
  Check(File.ReadAllText(stem+".ai-repair-report.txt").Contains("Số cue thay đổi lời: 1")&&StateFiles.Hash(p.Source)==hash,"Changed-cue count is exact and original SRT bytes are preserved");
  Check(FinalAudio.PcmFrames(output)==63600,"Full final WAV is exactly the original 2.65-second timeline");
  var restored=AiRepairSession.Restore(p.Report,used,Settings(),"fixture-profile",root);Check(restored!=null&&restored.Rows[0].Chosen!=null,"Accepted wording, measurements and history restore after restarting from final script");
  string[] hallucinations={"John did not expect the door to open after twelve days.","John expected the door to open that day.","Peter did not expect the door to open that day.","The door opened and John did not expect it that day."};
  foreach(string bad in hallucinations){var copy=VoiceRenderReport.Snapshot(original);copy[0].Text=bad;Check(RepairPolicy.Check(original,copy).Rejected,"Block invented/removed/reordered fact: "+bad);}
  var ambiguous=VoiceRenderReport.Snapshot(original);ambiguous[0].Text="John did not expect the door to open that day!";Check(!RepairPolicy.Check(original,ambiguous).Safe,"Changed sentence punctuation requires human review");
  var review=Open("review",One("John really did not expect the door to open that day.",2.9));var rw=new W{Reply=i=>Json(1,"John did not expect the door to open that day.")};Run(review,rw);
  Check(review.Rows[0].Best!=null&&review.Rows[0].Chosen==null&&review.Rows[0].Status.Contains("REVIEW REQUIRED"),"Timing-valid emphasis change is not silently auto-applied");AiTimeline.Accept(review,review.Rows[0],true);Check(review.Rows[0].Chosen.HumanApproved,"Review candidate applies only after explicit human acceptance");
  var failed=Open("three",One("John did not expect the door to open that day."));var fw=new W{Reply=i=>Json(1,"John did not expect the door to open that day and the ham began to glow.")};int before=E.Calls.Count;Run(failed,fw);
  Check(fw.Calls==3&&failed.Rows[0].AutoAttempts==3&&failed.Rows[0].Chosen==null,"Invalid AI output is limited to three trials and never marked fixed");Check(failed.Rows[0].Attempts.All(a=>a.Measurement==null)&&E.Calls.Count-before<=1,"Reject invented/duplicate wording before spending TTS work");
  Check(failed.Rows[0].Attempts.Last().Error.Contains("lặp"),"Repeated failed proposal is explicitly rejected rather than measured again");
  var engine=Open("engine",original);var never=new W{Reply=i=>"{}"};AiTimeline.Run(engine,never,role=>new E{Fail=true},()=>false,(i,m)=>{},true);Check(never.Calls==0&&engine.Rows[0].BaseStatus=="ENGINE ERROR","TTS/GPU failure is classified separately and never causes rewriting");
  string ffmpeg=Environment.GetEnvironmentVariable("V15_FFMPEG");try{Environment.SetEnvironmentVariable("V15_FFMPEG",Path.Combine(root,"missing-ffmpeg"));var audio=Open("audio",original);AiTimeline.Run(audio,never,New,()=>false,(i,m)=>{},true);Check(audio.Rows[0].CurrentMeasure.Kind=="AUDIO ERROR"&&never.Calls==0,"FFmpeg/fit failure is an audio error, not a wording error");}finally{Environment.SetEnvironmentVariable("V15_FFMPEG",ffmpeg);}
  Check(Tempo.Minimum(new RenderOptions{MinSpeed=.5})==.9&&Tempo.Maximum(new RenderOptions{GentleFit=false,MaxSpeed=1.6})==1.25,"Applied technical speed limits are 0.90–1.25x");Check(RepairPolicy.Quality(1.15).Contains("CẢNH BÁO"),"Above 1.10x has a distinct voice-quality warning");
  var dual=One("John did not expect the door to open that day.");dual[0].Speaker="B";var ds=Settings();ds.TwoVoices=true;ds.VoiceBKey="private:B";var dp=Open("dual",dual,ds);Run(dp,w);Check(dp.Rows[0].Chosen!=null&&dp.Rows[0].Chosen.Measurement.Voice=="Fixture B"&&dp.Effective()[0].Speaker=="B","AI repair measures B narration using B voice and preserves routing");
  var numeric=One("He paid $12 for lunch.");var changed=VoiceRenderReport.Snapshot(numeric);changed[0].Text="He paid -$12 for lunch.";Check(RepairPolicy.Check(numeric,changed).Rejected,"Reject changing a currency sign even when number words are unchanged");
  string models=Path.Combine(root,"ai/models/chatter_nano");Directory.CreateDirectory(models);string weight=Path.Combine(models,"t3_nano_v1.safetensors");File.WriteAllText(weight,"first model");var heavy=new E{Root=root,Kind=EngineKind.Chatterbox,ModelFolder="chatter_nano",VoiceName="clone",ReferencePath=""};string key=SpeechArchive.Key(heavy,"same sentence",1);File.WriteAllText(weight,"a different model revision");Check(key!=SpeechArchive.Key(heavy,"same sentence",1),"Chatterbox cache key changes with actual external model weights");
  var pause=Open("pause",original);bool cancelled=false;try{AiTimeline.Run(pause,w,New,()=>true,(i,m)=>{},true);}catch(OperationCanceledException){cancelled=true;}Check(cancelled&&pause.Effective()[0].Text==original[0].Text&&File.Exists(pause.Report),"Pause preserves source wording and a resumable state file");
  var during=Open("cancel-during-tts",original);var clock=System.Diagnostics.Stopwatch.StartNew();bool stoppedInside=false;try{AiTimeline.Run(during,w,role=>new SlowEngine{Root=root},()=>clock.ElapsedMilliseconds>150,(i,m)=>{},true);}catch(OperationCanceledException){stoppedInside=true;}Check(stoppedInside&&clock.Elapsed.TotalSeconds<2&&during.Rows[0].Chosen==null,"Pause actively cancels a TTS worker during measurement, not only between stages");
  // A failed second stage must not regenerate or refit a completed first stage.
  var parts=new List<Cue>{new Cue{Id=1,Start=0,End=3,Text="This small detail changes the whole story for everyone.",AnchorAfter=true},new Cue{Id=2,Start=3,End=6,Text="He was waiting there for a very long time because the door had finally opened."}};string rsource=Path.Combine(root,"resume.srt");File.WriteAllText(rsource,Scripts.ToSrt(parts));var ro=AudioRepair.Options(Settings(true).Xml().ToString());ro.CheckpointRoot=Path.Combine(root,"stages");ro.ReportContext=new VoiceReportContext{SourcePath=rsource,SourceCues=parts};bool rejected=false;try{using(var e=New("A"))Renderer.Render(parts,e,ro,Path.Combine(root,"resume.wav"),(i,m)=>{});}catch{rejected=true;}
  int firstReads=E.Calls.Count(t=>t==parts[0].Text);parts[1].Text="That small detail changes the whole story for everyone.";ro.ReportContext.SourceCues=VoiceRenderReport.Snapshot(parts);string resumed;using(var e=New("A"))resumed=Renderer.Render(parts,e,ro,Path.Combine(root,"resume.wav"),(i,m)=>{});
  Check(rejected&&E.Calls.Count(t=>t==parts[0].Text)==firstReads&&File.Exists(resumed),"Resume after a later-stage failure reuses the completed first-stage PCM checkpoint");
  Check(ro.RunReport.Units.First().CacheCalls>0&&FinalAudio.PcmFrames(resumed)==144000,"Resume records actual cache use and preserves exact full duration");
  var report=ro.RunReport;report.PathName=AiRepairSession.Unique(root,"fault-private",".txt");bool rollback=false;try{StableArtifacts.Publish(resumed,Path.Combine(root,"rollback.wav"),parts,ro,report,i=>{if(i==2)throw new IOException("injected disk failure");});}catch(IOException){rollback=true;}
  Check(rollback&&!Directory.GetFiles(root,"rollback*").Any(),"Sidecar commit failure rolls back the whole new group and exposes no WAV");
  var changedSource=One("This small detail changes the whole story for everyone.",3.2);string changedFile=Path.Combine(root,"external.srt");File.WriteAllText(changedFile,Scripts.ToSrt(changedSource));var externalOptions=new RenderOptions{Breathing=BreathMode.None,ReportContext=new VoiceReportContext{SourcePath=changedFile,SourceCues=changedSource}};bool externalBlocked=false;using(var e=New("A")){try{Renderer.Render(changedSource,e,externalOptions,Path.Combine(root,"external.wav"),(i,msg)=>{if(i==95)File.AppendAllText(changedFile,"\nchanged outside app");});}catch(IOException){externalBlocked=true;}}Check(externalBlocked&&!File.Exists(Path.Combine(root,"external.wav")),"A source changed during rendering cannot publish a stale synchronized output");
  // Stateful breathing must be identical between the AI probe and final render.
  Directory.CreateDirectory(Path.Combine(root,"breaths"));foreach(var item in new[]{new{File="a",Length=.208},new{File="b",Length=.254},new{File="c",Length=.286},new{File="d",Length=.315}})Tone(item.Length).Write(Path.Combine(root,"breaths",item.File+".wav"));
  var breathCues=new List<Cue>();for(int i=0;i<8;i++)breathCues.Add(new Cue{Id=i+1,Start=i*3.1,End=(i+1)*3.1,Text="This small detail changes the whole story for everyone.",AnchorAfter=i==3});var bs=Settings(true);bs.Breathing=0;bs.GentleFit=false;var bp=Open("breath",breathCues,bs);var none=new W{Reply=i=>"{}"};AiTimeline.Run(bp,none,New,()=>false,(i,m)=>{},false,false);
  Check(bp.Rows.Count==2&&bp.Rows[1].Original.BeforeBreath.Key==bp.Rows[0].Original.AfterBreath.Key,"AI stage probe carries the exact breathing state from the previous stage");
  var bo=AudioRepair.Options(bp.Settings);bo.AiRepair=bp;bo.ReportContext=new VoiceReportContext{SourcePath=bp.Source,SourceCues=breathCues};string bw;using(var e=New("A"))bw=Renderer.Render(breathCues,e,bo,Path.Combine(root,"breath.wav"),(i,m)=>{});
  Check(bp.Rows.All(r=>r.FinalVerified&&Math.Abs(r.FinalNatural-r.CurrentMeasure.Natural)<.00001),"Final render uses the same measured stage audio/breath context as the probe");
  Check(bp.Rows.All(r=>r.Status.StartsWith("FINAL VERIFIED"))&&!File.ReadAllText(Stem(bw)+".ai-repair-report.txt").Contains("Trạng thái: MANUAL REQUIRED"),"Final report has no contradictory unresolved stage status");
  Console.WriteLine("TOTAL STABLE REPAIR "+n+" passed. Synthetic TTS/rewriter and real FFmpeg; no physical Windows/GPU or model quality claim.\nFixtures: "+root);return 0;
 }catch(Exception ex){Console.WriteLine(ex);return 1;}}
}
